// Child Component Example
import React, { forwardRef, useImperativeHandle, useRef } from 'react';

const CustomInput = forwardRef((props, ref) => {
  const inputRef = useRef(); // Internal ref connected to the DOM node

  useImperativeHandle(ref, () => ({
    focus: () => inputRef.current.focus(),
    clear: () => (inputRef.current.value = ''),
    logValue: () => console.log(inputRef.current.value) // Logs the current value of the input
  }));

  return <input ref={inputRef} type='text' placeholder='Type something...' />;
});

export default CustomInput;

// Parent Component Example
import React, { useRef } from 'react';
import CustomInput from './CustomInput';

function Parent() {
  const customInputRef = useRef(); // External ref for the parent

  const handleFocus = () => {
    customInputRef.current.focus(); // Focus the input using the exposed method
  };

  const handleClear = () => {
    customInputRef.current.clear(); // Clear the input using the exposed method
  };

  const handleLog = () => {
    customInputRef.current.logValue(); // Log the input value using the exposed method
  };

  return (
    <div>
      <CustomInput ref={customInputRef} />
      <button onClick={handleFocus}>Focus Input</button>
      <button onClick={handleClear}>Clear Input</button>
      <button onClick={handleLog}>Log Input Value</button>
    </div>
  );
}

export default Parent;

